// The fields plugins add to Entity, by entity and field, shared by every
// plugin - the accessors on Entity are generated by scripts/player-fields.ts.
//
// A field is a key the module hands out for its name once (entity_field_key),
// the same to every plugin, which the accessors keep: a read is an index into
// the entity's values, not a name looked up. A value is a number or a text,
// as a player field's (PlayerValue). The engine counts an edict's lives in
// its serialnumber, which it moves when it frees one: values kept for an
// earlier life read as never written, so an entity that goes and its index
// taken again by a new one start over without a hook on every removal. A
// player's are cleared when he leaves, and every entity's when a map starts.
//
// Included by module.cpp, after the edicts' helpers (fields.h).

struct EntityFields {
	int serial;
	std::vector<PlayerValue> values;
};

static std::vector<EntityFields> g_entityFields;

/** The fields' keys by name: handed out once, kept for the module's life, as plugins keep them. */
static std::unordered_map<std::string, int32_t> g_entityFieldKeys;

/** entity_field_key(name) - the key of the field `name`, the same for every plugin. */
static int32_t w_entityFieldKey(wasm_exec_env_t env, int32_t name)
{
	std::string field = AsString(Inst(env), name);
	std::unordered_map<std::string, int32_t>::iterator found = g_entityFieldKeys.find(field);
	if (found != g_entityFieldKeys.end())
		return found->second;
	int32_t key = (int32_t)g_entityFieldKeys.size();
	g_entityFieldKeys[field] = key;
	return key;
}

/** Entity `id`'s value of `key` for its life now; NULL for no entity, or (not `make`) none kept. */
static PlayerValue *EntityValue(int32_t id, int32_t key, bool make)
{
	edict_t *e = (edict_t *)EdictOf(id);
	if (!e || key < 0)
		return NULL;
	if ((size_t)id >= g_entityFields.size()) {
		if (!make)
			return NULL;
		g_entityFields.resize(id + 1);
	}
	EntityFields &data = g_entityFields[id];
	if (data.serial != e->serialnumber) {
		data.values.clear();
		data.serial = e->serialnumber;
	}
	if ((size_t)key >= data.values.size()) {
		if (!make)
			return NULL;
		data.values.resize(key + 1);
	}
	return &data.values[key];
}

/** A player's: he left. */
static void ClearEntityFields(int id)
{
	if (id >= 0 && (size_t)id < g_entityFields.size())
		g_entityFields[id].values.clear();
}

static double w_entityDataGet(wasm_exec_env_t env, int32_t id, int32_t key)
{
	(void)env;
	const PlayerValue *found = EntityValue(id, key, false);
	return found && !found->text ? found->number : 0.0;
}

static void w_entityDataSet(wasm_exec_env_t env, int32_t id, int32_t key, double value)
{
	(void)env;
	PlayerValue *slot = EntityValue(id, key, true);
	if (!slot)
		return;
	slot->text = false;
	slot->number = value;
	slot->value.clear();
}

static int32_t w_entityDataGetText(wasm_exec_env_t env, int32_t id, int32_t key, int32_t out, int32_t max)
{
	const PlayerValue *found = EntityValue(id, key, false);
	return CopyText(Inst(env), found && found->text ? found->value : std::string(), out, max);
}

static void w_entityDataSetText(wasm_exec_env_t env, int32_t id, int32_t key, int32_t value)
{
	PlayerValue *slot = EntityValue(id, key, true);
	if (!slot)
		return;
	slot->text = true;
	slot->number = 0.0;
	slot->value = AsString(Inst(env), value);
}
